// ── Extract binary + parse EXIF ──────────────────────────────────
const binaryData = $input.item.binary;
const body = $input.item.json;

if (!binaryData || Object.keys(binaryData).length === 0) {
  throw new Error('No image received. In Postman: Body → form-data → key "data" → type File.');
}

const fieldName = Object.keys(binaryData)[0];
const field = binaryData[fieldName];
if (!field.data) throw new Error('File received but has no data.');

const base64   = field.data;
const mimeType = field.mimeType || 'image/jpeg';
const fileName = field.fileName || 'image.jpg';
const caption   = body?.caption   || null;
const claimDate = body?.claimDate || null;

// ── EXIF Parsing ─────────────────────────────────────────────────
const bytes = Buffer.from(base64, 'base64');
let exif = {
  hasExif: false, fileType: 'Unknown',
  dateTimeOriginal: null, modifyDate: null, wasEdited: false,
  make: null, software: null, gpsFound: false
};

const AI_TOOLS = [
  'Stable Diffusion','Midjourney','DALL-E','DALL·E','Adobe Firefly',
  'Canva','Runway','Pika','NovelAI','DreamStudio','ComfyUI','Automatic1111',
  'Bing Image Creator'
];
const CAMERAS = [
  'Canon','Nikon','Sony','Apple','Samsung','Google','Huawei',
  'OnePlus','Xiaomi','OPPO','Fujifilm','Panasonic','Leica','DJI','GoPro'
];

try {
  const isJpeg = bytes[0]===0xFF && bytes[1]===0xD8;
  const isPng  = bytes[0]===0x89 && bytes[1]===0x50;

  if (isJpeg) {
    exif.fileType = 'JPEG';
    const str = bytes.toString('binary');
    const exifIdx = str.indexOf('Exif');
    if (exifIdx !== -1) {
      exif.hasExif = true;
      const chunk = str.substring(exifIdx, exifIdx + 2048);
      const printable = chunk.replace(/[^\x20-\x7E]/g,'|').split('|').filter(s=>s.length>=3);
      const dates = chunk.match(/(\d{4}):(\d{2}):(\d{2}) (\d{2}):(\d{2}):(\d{2})/g) || [];
      if (dates[0]) exif.dateTimeOriginal = dates[0].replace(/(\d{4}):(\d{2}):(\d{2})/,'$1-$2-$3');
      if (dates[1]) {
        exif.modifyDate = dates[1].replace(/(\d{4}):(\d{2}):(\d{2})/,'$1-$2-$3');
        exif.wasEdited  = dates[0] !== dates[1];
      }
      exif.gpsFound = chunk.includes('GPS');
      for (const s of printable) {
        for (const ai of AI_TOOLS) {
          if (s.toLowerCase().includes(ai.toLowerCase())) { exif.software=ai; break; }
        }
        if (exif.software) break;
      }
      for (const s of printable) {
        for (const cam of CAMERAS) {
          if (s.toLowerCase().includes(cam.toLowerCase()) && !exif.make) { exif.make=s.trim().substring(0,40); }
        }
      }
    }
  }
  if (isPng) {
    exif.fileType = 'PNG';
    const str = bytes.toString('binary');
    for (const ai of AI_TOOLS) { if (str.includes(ai)) { exif.software=ai; exif.hasExif=true; break; } }
    if (str.includes('Steps:')||str.includes('Sampler:')||str.includes('parameters')) {
      if (!exif.software) exif.software='AI Generator (SD metadata)';
      exif.hasExif = true;
    }
  }
} catch(e) { exif.parseError = e.message; }

const currentYear = new Date().getFullYear();
let exifAgeWarning = null;
let exifInsight = 'No EXIF data — likely screenshot or downloaded.';

if (exif.software) {
  exifInsight = `🚨 AI SOFTWARE IN METADATA: "${exif.software}"`;
} else if (exif.wasEdited) {
  exifInsight = `⚠️ File modified after creation. Created: ${exif.dateTimeOriginal} | Modified: ${exif.modifyDate}`;
} else if (exif.dateTimeOriginal) {
  const yr = parseInt(exif.dateTimeOriginal.substring(0,4));
  if (!isNaN(yr) && yr < currentYear-2) {
    exifAgeWarning = `Photo taken in ${yr} — ${currentYear-yr} years ago.`;
    exifInsight = `⚠️ ${exifAgeWarning}`;
  } else {
    exifInsight = `Photo taken: ${exif.dateTimeOriginal}${exif.make?' | Camera: '+exif.make:''}`;
  }
} else if (exif.hasExif) {
  exifInsight = `EXIF found${exif.make?' | Camera: '+exif.make:''} | No date recorded.`;
}

return [{
  json: { base64, mimeType, fileName, caption, claimDate, exif, exifAgeWarning, exifInsight, currentYear },
  binary: { data: { ...field } }
}];

const wvolfRaw = $input.item.json;
const prev = $('📦 Extract Base64 + EXIF').first();

let deepfakeScore = 50;

// Handle BOTH: single object {label, score} OR array [{label,score}]
const entries = Array.isArray(wvolfRaw) ? wvolfRaw : [wvolfRaw];

const fake = entries.find(r => r.label?.toLowerCase() === 'fake');
const real = entries.find(r => r.label?.toLowerCase() === 'real');

if (fake) deepfakeScore = Math.round(fake.score * 100);
else if (real) deepfakeScore = Math.round((1 - real.score) * 100);
else deepfakeScore = -1;

return [{
  json: { ...prev.json, deepfakeScore },
  binary: prev.binary
}];

const dima806Raw = $input.item.json;
const prev = $('💾 Save Wvolf Score').first();

let aiGenScore = 50;

// Handle BOTH: single object OR array
const entries = Array.isArray(dima806Raw) ? dima806Raw : [dima806Raw];

const fake = entries.find(r => r.label?.toUpperCase() === 'FAKE');
const real = entries.find(r => r.label?.toUpperCase() === 'REAL');

if (fake) aiGenScore = Math.round(fake.score * 100);
else if (real) aiGenScore = Math.round((1 - real.score) * 100);
else aiGenScore = -1;

return [{
  json: { ...prev.json, aiGenScore },
  binary: prev.binary
}];

// Save imgbb URL, carry everything forward
const imgbbRaw = $input.item.json;
const prev = $('💾 Save dima806 Score').first();

const imageUrl = imgbbRaw?.data?.url || null;
if (!imageUrl) throw new Error('imgbb upload failed. Check your IMGBB_KEY_HERE value.');

return [{
  json: { ...prev.json, imageUrl }
}];

// ── All data is now in one place — build Gemini prompt ──
const serpRaw = $input.item.json;
const prev = $('💾 Save imgbb URL').first().json;

const { base64, mimeType, fileName, caption, claimDate, exif, exifAgeWarning, exifInsight, currentYear, deepfakeScore, aiGenScore } = prev;

// ── Parse SerpAPI (graceful — handles 503, error objects, empty results) ──
// When SerpAPI fails + "Continue on Error" is set, n8n passes error object
// We safely fall back to empty results in all failure cases
const imageResults = Array.isArray(serpRaw?.image_results) ? serpRaw.image_results : [];
const totalResults = imageResults.length;
const topSources = imageResults.slice(0,5).map(r => ({
  source:  r.source || r.link || 'Unknown',
  title:   r.title  || 'Unknown',
  snippet: r.snippet || ''
}));
const allText = imageResults.map(r=>(r.snippet||'')+' '+(r.title||'')).join(' ');
const yearsFound = [...new Set((allText.match(/\b(19|20)\d{2}\b/g)||[]))].sort();
const earliestYear = yearsFound.length > 0 ? parseInt(yearsFound[0]) : null;

// ── Context strings for Gemini ──
const hfContext = [
  deepfakeScore >= 0
    ? `Deepfake Face Classifier (Wvolf ViT, 98.7% lab accuracy): ${deepfakeScore}% probability FAKE`
    : 'Deepfake classifier: unavailable',
  aiGenScore >= 0
    ? `AI Generation Classifier (dima806 ViT, 98.25% lab accuracy): ${aiGenScore}% probability AI-GENERATED`
    : 'AI generation classifier: unavailable'
].join('\n');

const exifContext = exif.software
  ? `STRONG SIGNAL — AI software in EXIF: "${exif.software}"`
  : exif.dateTimeOriginal
    ? `Date taken: ${exif.dateTimeOriginal}${exif.make?' | Camera: '+exif.make:''}${exif.wasEdited?' | FILE EDITED AFTER CREATION':''}`
    : 'No EXIF metadata (screenshot or stripped)';

const serpContext = earliestYear
  ? `Found ${totalResults} prior web appearances. Earliest year: ${earliestYear}. Top sources: ${topSources.slice(0,3).map(s=>s.source).join(', ')}`
  : totalResults>0
    ? `Found ${totalResults} appearances but no specific date found`
    : serpRaw?.error
      ? `Reverse image search unavailable (${serpRaw.error})`
      : 'No prior appearances found in reverse image search';

const claimContext = (caption||claimDate)
  ? `Caption: "${caption||'none'}" | Claimed date: "${claimDate||'none'}"`
  : 'No caption or date claim provided';

const prompt = `You are an expert forensic image analyst. Carefully analyze this image.

═══ SIGNALS FROM OTHER DETECTION SYSTEMS ═══
${hfContext}
EXIF: ${exifContext}
Reverse Search: ${serpContext}
User Claim: ${claimContext}

═══ YOUR FORENSIC TASK ═══
Form your OWN independent visual judgment. Do NOT just repeat the scores above.
Then state whether you AGREE or DISAGREE with the classifiers and why.

1. DEEPFAKE SIGNS — check for:
- Face boundary artifacts (blurring/halos at jaw/hairline)
- Skin tone mismatch at face/neck edges
- Unnatural eye reflections or glassy stare
- Hair edge artifacts or pixelation at boundary
- Lighting mismatch between face and background
- Stiff or unnatural facial expression

2. AI GENERATION SIGNS — check for:
- Skin texture too smooth, waxy, or plastic-like
- Wrong number of fingers or morphed hands
- Blurry, illegible, or hallucinated text in image
- Unnaturally perfect facial symmetry
- Dreamlike background or unnatural bokeh
- Repeated background patterns
- Inconsistent or impossible light sources

3. GENERAL INCONSISTENCIES — check for:
- Shadows that do not match light direction
- Objects that look copy-pasted
- Perspective or scale errors
- Elements that defy physics

4. CONTEXT CLUES — check for:
- Any visible text (news tickers, signs, watermarks, dates)?
- What technology era does this suggest (phone models, car models, fashion)?
- Does anything contradict the claimed date "${claimDate||'not provided'}"?

Return ONLY raw JSON. No markdown. No backticks. Nothing else:
{
  "deepfake_visual": { "score": <0-100>, "reasoning": "<what you specifically saw or did not see>" },
  "ai_gen_visual":   { "score": <0-100>, "reasoning": "<what you specifically saw or did not see>" },
  "inconsistencies": ["<specific finding 1>", "<specific finding 2>"],
  "context_clues":   ["<visible text, date, tech, or era clue>"],
  "agrees_with_classifiers": <true or false>,
  "disagreement_reason": "<if false, explain why>",
  "gemini_verdict": "<REAL | DEEPFAKE | AI_GENERATED | SUSPICIOUS | INCONCLUSIVE>",
  "confidence": <0-100>,
  "summary": "<2-3 sentence forensic conclusion in plain English>"
}`;

return [{
  json: {
    base64, mimeType, fileName, caption, claimDate,
    exif, exifAgeWarning, exifInsight, currentYear,
    deepfakeScore, aiGenScore,
    earliestYear, topSources, totalResults,
    geminiPrompt: prompt
  }
}];

const geminiRaw = $input.item.json;
const prev = $('🧠 Prepare Gemini Context').first().json;

const { deepfakeScore, aiGenScore, earliestYear, topSources, totalResults, exif, exifAgeWarning, currentYear, claimDate, caption, fileName, exifInsight } = prev;

// ── Parse Gemini JSON ──
const gText = geminiRaw.candidates?.[0]?.content?.parts?.[0]?.text || '';
let g;
try {
  g = JSON.parse(gText.replace(/```json|```/g,'').trim());
} catch(e) {
  g = {
    deepfake_visual:  { score:50, reasoning:'Gemini parse failed — using classifier scores only.' },
    ai_gen_visual:    { score:50, reasoning:'Gemini parse failed — using classifier scores only.' },
    inconsistencies:  ['Gemini analysis unavailable. Manual review required.'],
    context_clues:    [],
    agrees_with_classifiers: true,
    disagreement_reason: '',
    gemini_verdict:   'INCONCLUSIVE',
    confidence:       20,
    summary:          'Automated forensic analysis was inconclusive. Manual review required.'
  };
}

// ── Combine HF + Gemini scores (50/50) ──
let combinedDeepfake = deepfakeScore >= 0
  ? Math.round((deepfakeScore * 0.5) + (g.deepfake_visual.score * 0.5))
  : g.deepfake_visual.score;

let combinedAiGen = aiGenScore >= 0
  ? Math.round((aiGenScore * 0.5) + (g.ai_gen_visual.score * 0.5))
  : g.ai_gen_visual.score;

// EXIF hard override
if (exif.software) combinedAiGen = Math.max(combinedAiGen, 92);

// ── Timeliness Score ──
let timelyScore = 70;
let timelyReasoning = 'No reverse search results to evaluate timeline.';
let serpVerdict = 'NO_DATA';

let claimYear = null;
if (claimDate) { const m=claimDate.match(/\b(19|20)\d{2}\b/); if(m) claimYear=parseInt(m[0]); }

if (earliestYear) {
  const ageYears = currentYear - earliestYear;
  if (claimYear) {
    const diff = claimYear - earliestYear;
    if (Math.abs(diff)<=1)  { timelyScore=92; serpVerdict='CLAIM_MATCHES';  timelyReasoning=`✅ Claimed (${claimYear}) matches earliest found (${earliestYear}).`; }
    else if (diff>1)        { timelyScore=5;  serpVerdict='CLAIM_MISMATCH'; timelyReasoning=`🚨 MISMATCH: Claimed ${claimYear} but image first appeared online in ${earliestYear} — ${diff} years earlier.`; }
    else                    { timelyScore=60; serpVerdict='MINOR_MISMATCH'; timelyReasoning=`Minor gap: claimed ${claimYear}, earliest found ${earliestYear}.`; }
  } else {
    if (ageYears>=3)      { timelyScore=12; serpVerdict='LIKELY_OLD';    timelyReasoning=`Image from ${earliestYear} — ${ageYears} years ago. HIGH risk of reshare.`; }
    else if (ageYears>=1) { timelyScore=48; serpVerdict='POSSIBLY_OLD';  timelyReasoning=`First appeared ~${earliestYear}. May be reshared.`; }
    else                  { timelyScore=88; serpVerdict='LIKELY_RECENT'; timelyReasoning=`Appears recent (first found ${earliestYear}).`; }
  }
  timelyReasoning += ` Found ${totalResults} total appearances.`;
} else if (totalResults>0) {
  timelyScore=60; serpVerdict='UNVERIFIED'; timelyReasoning=`Found ${totalResults} appearances but no date determined.`;
} else {
  timelyScore=70; serpVerdict='NO_PRIOR_RECORD'; timelyReasoning='No prior appearances found. Image may be new or not indexed.';
}

if (exifAgeWarning) { timelyScore=Math.min(timelyScore,18); timelyReasoning=exifAgeWarning+' '+timelyReasoning; }

// ── Formula ──
const ai_real     = 100 - combinedAiGen;
const no_deepfake = 100 - combinedDeepfake;
const timely      = timelyScore;
const overall     = Math.round((ai_real*0.35)+(no_deepfake*0.35)+(timely*0.30));
const flagged     = overall < 75;

// ── Final Verdict ──
let finalVerdict, alertLevel, verdictEmoji;
if      (exif.software)                                              { finalVerdict='AI GENERATED — CONFIRMED BY METADATA'; verdictEmoji='🤖'; alertLevel='HIGH'; }
else if (combinedAiGen>=80)                                          { finalVerdict='AI GENERATED';                         verdictEmoji='🤖'; alertLevel='HIGH'; }
else if (combinedDeepfake>=78)                                       { finalVerdict='DEEPFAKE DETECTED';                    verdictEmoji='👤'; alertLevel='HIGH'; }
else if (serpVerdict==='CLAIM_MISMATCH'||serpVerdict==='LIKELY_OLD') { finalVerdict='MISCLAIMED / OLD PHOTO';               verdictEmoji='⏳'; alertLevel='HIGH'; }
else if (overall<40)                                                 { finalVerdict='ALMOST CERTAINLY FAKE';                verdictEmoji='🔴'; alertLevel='HIGH'; }
else if (overall<75)                                                 { finalVerdict='SUSPICIOUS — NEEDS REVIEW';            verdictEmoji='⚠️'; alertLevel='MEDIUM'; }
else if (overall>=85)                                                { finalVerdict='LIKELY REAL & TIMELY';                 verdictEmoji='✅'; alertLevel='LOW'; }
else                                                                 { finalVerdict='PROBABLY REAL';                        verdictEmoji='✅'; alertLevel='LOW'; }

// ── Red Flags ──
const redFlags = [
  exif.software                  && `🤖 EXIF contains AI software: "${exif.software}"`,
  exifAgeWarning                 && `📅 ${exifAgeWarning}`,
  exif.wasEdited                 && `✏️ File modified after creation (${exif.modifyDate})`,
  !exif.hasExif                  && `🗂️ No EXIF — screenshot or stripped`,
  serpVerdict==='CLAIM_MISMATCH' && `🚨 Claimed ${claimYear} ≠ earliest found ${earliestYear}`,
  serpVerdict==='LIKELY_OLD'     && `⏳ Image from ${earliestYear} — ${currentYear-earliestYear} years ago`,
  combinedDeepfake>=75           && `👤 Deepfake: ${combinedDeepfake}% (HF:${deepfakeScore}% | Gemini:${g.deepfake_visual.score}%)`,
  combinedAiGen>=75              && `🤖 AI-gen: ${combinedAiGen}% (HF:${aiGenScore}% | Gemini:${g.ai_gen_visual.score}%)`,
  !g.agrees_with_classifiers     && `⚡ Gemini disagrees: ${g.disagreement_reason}`
].filter(Boolean);

return [{
  json: {
    fileName, caption, claimDate,
    finalVerdict, verdictEmoji, alertLevel,
    formula: { ai_real, no_deepfake, timely, overall, flagged, calculation:`(${ai_real}×0.35)+(${no_deepfake}×0.35)+(${timely}×0.30)=${overall}%` },
    scores: {
      deepfake:     { hf:deepfakeScore,  gemini:g.deepfake_visual.score, combined:combinedDeepfake },
      ai_generated: { hf:aiGenScore,     gemini:g.ai_gen_visual.score,   combined:combinedAiGen },
      timely: timelyScore
    },
    reasoning: {
      deepfake:       g.deepfake_visual.reasoning,
      ai_generated:   g.ai_gen_visual.reasoning,
      timeline:       timelyReasoning,
      gemini_summary: g.summary
    },
    redFlags,
    inconsistencies:       g.inconsistencies   || [],
    contextClues:          g.context_clues     || [],
    geminiVerdict:         g.gemini_verdict,
    geminiConfidence:      g.confidence,
    agreesWithClassifiers: g.agrees_with_classifiers,
    disagreementReason:    g.disagreement_reason || null,
    reverseSearch: { totalResults, earliestYear, serpVerdict, topSources },
    exif: {
      hasExif:   exif.hasExif, fileType: exif.fileType,
      dateTaken: exif.dateTimeOriginal, modifyDate: exif.modifyDate,
      wasEdited: exif.wasEdited, camera: exif.make,
      software:  exif.software, gpsFound: exif.gpsFound,
      insight:   exifInsight
    },
    analyzedAt: new Date().toISOString()
  }
}];
